 if(!b)for(const id of selected){const building=state.buildings.find(v=>v.id===id);if(building){const size=BUILDINGS[building.type].size;for(const[dx,dy,w,h]of[[size/2,0,size,.035],[size/2,size,size,.035],[0,size/2,.035,size],[size,size/2,.035,size]])part(this.rings,'box',this.M.selection,building.x+dx,.03,building.y+dy,w,.02,h);}}
