function clampCamera(v){return Math.max(5,Math.min(27,v));}
let thumbRenderer,thumbScene,thumbCamera,thumbM;const thumbnails=new Map();
export function thumbnail(type,level=1,isUnit=false){const key=type+':'+level+':'+isUnit;if(thumbnails.has(key))return thumbnails.get(key);if(!thumbRenderer){thumbRenderer=new T.WebGLRenderer({alpha:true,antialias:true});thumbRenderer.setSize(180,170);thumbRenderer.outputColorSpace=T.SRGBColorSpace;thumbRenderer.toneMapping=T.ACESFilmicToneMapping;thumbRenderer.toneMappingExposure=1.15;thumbScene=new T.Scene();thumbScene.add(new T.HemisphereLight('#edf4ff','#7b6b4d',2));const light=new T.DirectionalLight('#fff1cc',3.5);light.position.set(-3,5,4);thumbScene.add(light);thumbScene.add(new T.AmbientLight('#c7dbe2',.4));thumbCamera=new T.OrthographicCamera(-2,2,2,-2,.1,30);thumbM=materials();}const g=isUnit?createActor(type,level,thumbM):createBuilding(type,level,thumbM);if(!g.userData.creature&&!g.userData.siegeArm&&isUnit)animateUnit(g,{type:UNITS[type].model,cooldown:0},1,false,false,false);g.updateMatrixWorld(true);const bounds=new T.Box3().setFromObject(g),size=bounds.getSize(new T.Vector3()),center=bounds.getCenter(new T.Vector3()),half=Math.max(size.x,size.y,size.z)*.68;Object.assign(thumbCamera,{left:-half*1.06,right:half*1.06,top:half,bottom:-half});thumbCamera.position.copy(center).add(new T.Vector3(isUnit?1.5:3,2.2,4));thumbCamera.lookAt(center);thumbCamera.updateProjectionMatrix();thumbScene.add(g);thumbRenderer.render(thumbScene,thumbCamera);const url=thumbRenderer.domElement.toDataURL();g.removeFromParent();g.userData.mixer?.stopAllAction();thumbnails.set(key,url);return url;}
